using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
// In .NET 9+ there's a generic overload on the options object via the
// IJsonTypeInfoResolver interface. The simplest strongly-typed path is:
JsonTypeInfo<Person> typed = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got JsonTypeInfo<Person> – Kind: {typed.Kind}, Type: {typed.Type.Name}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
//    For a type the resolver CAN produce metadata for:
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"TryGetTypeInfo(Person): found={found}, info is null={info is null}");

//    For a type the resolver CANNOT produce metadata for (e.g., a Span or ref struct),
//    or when using a source-gen resolver that doesn't include the type:
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty composite – resolves nothing
};

bool found2 = restrictedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo(Person) on empty resolver: found={found2}, info is null={info2 is null}");

public record Person(string Name, int Age);

